INSERT INTO "classifications" VALUES(480,'claude-haiku-5-5','2026-10-17T08:53:45Z',1,0.93,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.93, "countries": [], "event_date": "2026-10-14", "institutions": [{"country": null, "name": "European Centre for Medium-Range Weather Forecasts", "short_name": "ECMWF", "type": "WMO_centre"}, {"country": null, "name": "Microsoft Research", "short_name": "Microsoft Research", "type": "private_sector"}, {"country": null, "name": "Massachusetts Institute of Technology", "short_name": "MIT", "type": "research"}], "language": "es", "news_type": "pilot_research", "original_title": "IA mejora el pronóstico meteorológico a largo plazo", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A new AI tool developed by researchers at Microsoft Research and MIT improves the accuracy of subseasonal forecasts from the ECMWF model. The system is aimed at optimising agricultural and energy management decisions.", "summary_original": "Una nueva herramienta de IA desarrollada por investigadores de Microsoft Research y MIT mejora la precisión de las previsiones subestacionales del modelo del ECMWF, con aplicaciones en la gestión agrícola y energética.", "system_name": null, "techniques": ["ml_dl"], "title_en": "AI improves long-range weather forecasting", "value_added": "Improves the accuracy of long-range (subseasonal) weather forecasts, supporting agricultural and energy management.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(481,'claude-haiku-5-5','2026-10-17T08:53:18Z',1,0.9,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.9, "countries": [], "event_date": "2026-10-14", "institutions": [], "language": "es", "news_type": "pilot_research", "original_title": "IA mejora el pronóstico meteorológico a 6 semanas", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "According to a study published in Nature, an AI approach learns to correct errors of existing weather prediction models, improving results at two to six weeks lead time. The authors highlight potential benefits for disaster preparedness in vulnerable communities.", "summary_original": "Según un artículo publicado en Nature, la IA aprende a corregir errores de modelos de predicción existentes para mejorar resultados entre dos y seis semanas. Los autores señalan potencial para mejorar la preparación ante desastres en comunidades vulnerables.", "system_name": null, "techniques": ["ml_dl"], "title_en": "AI improves 6-week weather forecasting", "value_added": "Improves forecast skill between two and six weeks ahead by learning to correct errors of existing prediction models.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(482,'claude-haiku-5-5','2026-10-17T08:53:22Z',1,0.85,0,'{"areas": ["forecasting"], "confidence": 0.85, "countries": [], "event_date": "2026-10-14", "institutions": [], "language": "es", "news_type": "pilot_research", "original_title": "Una nueva herramienta de IA mejora el pronóstico meteorológico a un plazo de 2 a 6 semanas - Infobae", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A news item reports, citing EFE, a new AI tool that improves the prediction of extreme weather events at a 2 to 6 week range, a period where forecasts are currently considered unreliable. The developing institution and model name are not identified in the snippet.", "summary_original": "Según la agencia EFE, una nueva herramienta de IA mejora la predicción de fenómenos meteorológicos extremos en un plazo de dos a seis semanas, un rango en el que las previsiones son poco fiables.", "system_name": null, "techniques": ["ml_dl"], "title_en": "A new AI tool improves weather forecasting at a 2 to 6 week range", "value_added": "Improves prediction of extreme weather phenomena at 2-6 week lead times, where forecasts are described as unreliable.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(483,'claude-haiku-5-5','2026-10-17T08:53:54Z',1,0.9,0,'{"areas": ["forecasting"], "confidence": 0.9, "countries": ["US"], "event_date": "2026-10-16", "institutions": [{"country": "US", "name": "Massachusetts Institute of Technology", "short_name": "MIT", "type": "research"}, {"country": "US", "name": "Microsoft", "short_name": "Microsoft", "type": "private_sector"}], "language": "es", "news_type": "pilot_research", "original_title": "Una IA logra pronosticar tormentas con un mes de antelación", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Researchers from MIT and Microsoft developed an AI that anticipates extreme storms two to six weeks before they occur. According to the article, the program predicted in January the winter storm Hernando, which affected the United States a month later.", "summary_original": "Investigadores del MIT y Microsoft desarrollaron una IA que anticipa tormentas extremas entre dos y seis semanas antes. Según el artículo, el programa anticipó en enero la tormenta invernal Hernando que afectó Estados Unidos un mes después.", "system_name": null, "techniques": ["ml_dl"], "title_en": "An AI manages to forecast storms a month in advance", "value_added": "Anticipates extreme storms between two and six weeks in advance, as reported by the article.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(484,'claude-haiku-5-5','2026-10-17T08:53:27Z',1,0.9,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.9, "countries": [], "event_date": "2026-10-16", "institutions": [{"country": null, "name": "Microsoft Research", "short_name": "Microsoft Research", "type": "private_sector"}, {"country": "US", "name": "Massachusetts Institute of Technology", "short_name": "MIT", "type": "research"}], "language": "es", "news_type": "pilot_research", "original_title": "Las lluvias y los eventos extremos, bajo la lupa de una IA creada por científicos del MIT - Infobae", "primary_area": "guidance", "relevant": true, "review": false, "summary_en": "A study published in Nature describes a probabilistic bias-correction AI tool developed by Microsoft Research and MIT that raises the accuracy of temperature, pressure and precipitation forecasts up to six weeks in advance. The tool is presented as a complement to, not a replacement for, the systems already used by meteorological services.", "summary_original": "Una herramienta de corrección probabilística de sesgos de Microsoft Research y MIT eleva la precisión de pronósticos de temperatura, presión y precipitación hasta seis semanas antes, según un estudio en Nature. No reemplaza los sistemas que ya usan los servicios meteorológicos.", "system_name": null, "techniques": ["ml_dl"], "title_en": "Rainfall and extreme events under the lens of an AI created by MIT scientists", "value_added": "Improves the accuracy of temperature, pressure and precipitation forecasts up to six weeks ahead through probabilistic bias correction.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(485,'claude-haiku-5-5','2026-10-17T08:53:30Z',1,0.9,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.9, "countries": [], "event_date": "2026-10-14", "institutions": [{"country": null, "name": "Microsoft Research", "short_name": "Microsoft Research", "type": "private_sector"}, {"country": "US", "name": "Massachusetts Institute of Technology", "short_name": "MIT", "type": "research"}], "language": "es", "news_type": "pilot_research", "original_title": "IA del MIT revoluciona pronósticos de lluvias y eventos extremos - KCH FM", "primary_area": "guidance", "relevant": true, "review": false, "summary_en": "Microsoft Research and MIT developed an AI system, published in Nature on 14 October, that corrects systematic biases in existing weather models at two to six week lead times. It works as a post-processing layer on top of current forecast models, aiming to improve rainfall and extreme event predictions.", "summary_original": "El sistema de IA de Microsoft Research y MIT, divulgado el 14 de octubre en Nature, corrige fallos sistemáticos de modelos meteorológicos a dos a seis semanas. Actúa como una capa de ajuste posterior sobre los modelos existentes.", "system_name": null, "techniques": ["ml_dl"], "title_en": "MIT AI revolutionises rainfall and extreme event forecasts", "value_added": "Corrects systematic errors of existing weather models at two to six weeks lead time as a post-processing adjustment layer.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(486,'claude-haiku-5-5','2026-10-17T08:53:32Z',0,0.95,0,'{"areas": ["other"], "confidence": 0.95, "countries": ["MX"], "event_date": "2026-10-16", "institutions": [{"country": "MX", "name": "Servicio Meteorológico Nacional de México", "short_name": "SMN", "type": "NMHS"}], "language": "es", "news_type": "other", "original_title": "Adiós al calor: Así afectará el frente frío 2 a tu ciudad en las próximas horas", "primary_area": "other", "relevant": false, "review": false, "summary_en": "News item reporting a cold front alert issued by Mexico''s National Meteorological Service for October 16, 2026, with temperature drops and heavy rain. No artificial intelligence is mentioned, so the item is not relevant to AI in NMHS operations.", "summary_original": "Nota sobre una alerta del Servicio Meteorológico Nacional de México por un frente frío con descenso de temperaturas y lluvias intensas el 16 de octubre de 2026. No menciona inteligencia artificial.", "system_name": null, "techniques": [], "title_en": "Goodbye to the heat: How cold front 2 will affect your city in the coming hours", "value_added": null, "value_types": [], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(611,'claude-haiku-5-5','2026-10-17T08:55:39Z',1,0.95,0,'{"areas": ["forecasting"], "confidence": 0.95, "countries": [], "event_date": "2026-10-12", "institutions": [{"country": null, "name": "European Centre for Medium-Range Weather Forecasts", "short_name": "ECMWF", "type": "WMO_centre"}], "language": "en", "news_type": "model_release", "original_title": "Bringing the surface ocean into the AIFS", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "ECMWF announces an extension of its AIFS machine-learning forecasting system that jointly models the atmosphere, ocean waves, sea ice and the surface ocean. The system integrates these components within one ML model, extending AI-based forecasting beyond the atmosphere to marine and ice conditions.", "summary_original": null, "system_name": "AIFS", "techniques": ["ai_weather_model", "ml_dl"], "title_en": "Bringing the surface ocean into the AIFS", "value_added": "Joint machine-learning model covering the atmosphere, waves, sea ice and the surface ocean in a single system.", "value_types": ["other"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(644,'claude-haiku-5-5','2026-10-17T08:55:44Z',1,0.7,0,'{"areas": ["operations", "other"], "confidence": 0.7, "countries": ["JP"], "event_date": "2026-10-12", "institutions": [{"country": null, "name": "United Nations Office for Disaster Risk Reduction", "short_name": "UNDRR", "type": "international"}, {"country": null, "name": "Office of Digital Evolution and Transformation (UNDRR–ODET initiative)", "short_name": "ODET", "type": "international"}], "language": "en", "news_type": "event_conference", "original_title": "Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "primary_area": "operations", "relevant": true, "review": false, "summary_en": "UNDRR convened governments, tech companies and researchers in Tokyo to advance responsible use of AI and emerging technologies for disaster risk reduction. The workshop aimed to shape a joint UNDRR–ODET initiative covering knowledge sharing, peer exchange, matchmaking and pilot projects. The item is about AI for disaster risk reduction in general, with no specific model or NMHS deployment named.", "summary_original": null, "system_name": null, "techniques": ["ml_dl", "other"], "title_en": "Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "value_added": null, "value_types": ["other"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(652,'claude-haiku-5-5','2026-10-17T08:55:41Z',1,0.8,0,'{"areas": ["warnings", "operations", "other"], "confidence": 0.8, "countries": ["JP"], "event_date": "2026-10-02", "institutions": [{"country": null, "name": "United Nations Office for Disaster Risk Reduction", "short_name": "UNDRR", "type": "international"}, {"country": "JP", "name": "Japan International Cooperation Agency", "short_name": "JICA", "type": "other_national_agency"}], "language": "en", "news_type": "event_conference", "original_title": "World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "primary_area": "other", "relevant": true, "review": false, "summary_en": "UNDRR, with support from the Government of Japan and JICA, convened governments, technology companies, researchers and international organizations in Tokyo on 1-2 October 2026 to discuss how AI and other emerging technologies can become practical disaster risk reduction tools. The workshop focused on pathways from technology to applied use in disaster risk reduction.", "summary_original": null, "system_name": null, "techniques": ["ml_dl", "other"], "title_en": "World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "value_added": "Explores how artificial intelligence and other emerging technologies can be translated into practical tools for reducing disaster risk.", "value_types": ["other"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(675,'claude-haiku-5-5','2026-10-17T08:55:46Z',1,0.6,0,'{"areas": ["forecasting", "observations"], "confidence": 0.6, "countries": ["KR"], "event_date": "2026-10-09", "institutions": [{"country": "KR", "name": "Korea Polar Research Institute", "short_name": "KOPRI", "type": "research"}], "language": "en", "news_type": "other", "original_title": "Reliable AI Sea Ice Forecasts Depend on Sustained Observations", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "The article argues that AI-based sea ice prediction systems need sustained in-situ observations for validation. It cites an on-ice measurement campaign in the Southern Ocean supported by the Korean icebreaker R/V Araon conducted by KOPRI. The item concerns AI sea ice forecasting, which is a weather/climate-related application, though the snippet is brief.", "summary_original": null, "system_name": null, "techniques": ["ai_weather_model", "ml_dl"], "title_en": "Reliable AI Sea Ice Forecasts Depend on Sustained Observations", "value_added": null, "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(684,'claude-haiku-5-5','2026-10-17T08:55:37Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": ["US"], "event_date": "2026-06-08", "institutions": [{"country": "US", "name": "SpaceX", "short_name": "SpaceX", "type": "private_sector"}], "language": "ja", "news_type": "other", "original_title": "宇宙データセンター", "primary_area": "other", "relevant": false, "review": false, "summary_en": "The article covers the push by US big tech, including SpaceX, toward orbital AI data centers, with SpaceX announcing its first AI data-center satellite ''AI1'' in June 2026. The item concerns space-based computing infrastructure and does not describe AI being developed or used for weather, water, climate, early warning or disaster risk reduction.", "summary_original": "2026年に入り、米ビッグテックが宇宙データセンターの実現に向けた動きを加速させている。米SpaceXは2026年6月8日、衛星軌道上で運用するAIデータセンター衛星の初号機「AI1」の概要を公表した。", "system_name": null, "techniques": [], "title_en": "Space data centers", "value_added": null, "value_types": [], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(712,'claude-haiku-5-5','2026-10-17T08:55:35Z',1,0.6,0,'{"areas": ["warnings", "operations"], "confidence": 0.6, "countries": ["ES"], "event_date": "2026-10-13", "institutions": [{"country": "ES", "name": "Agencia Estatal de Meteorología", "short_name": "AEMET", "type": "NMHS"}], "language": "es", "news_type": "event_conference", "original_title": "Hugo Morán defiende la cooperación iberoamericana para mejorar la prevención de ...", "primary_area": "warnings", "relevant": true, "review": false, "summary_en": "At a meeting in Madrid of water, meteorology and civil protection leaders chaired by the president of AEMET, participants stressed sharing technical capacities, strengthening early warning systems and using artificial intelligence to anticipate droughts, floods and other extreme events. AI is mentioned as a future-oriented opportunity rather than a specific deployed system.", "summary_original": "En una reunión en Madrid de responsables de agua, meteorología y protección civil, presidida por el presidente de AEMET, se destacó compartir capacidades técnicas, reforzar los sistemas de alerta temprana y aprovechar la inteligencia artificial para anticipar sequías, inundaciones y otros fenómenos extremos.", "system_name": null, "techniques": ["ml_dl"], "title_en": "Hugo Morán defends Ibero-American cooperation to improve disaster prevention", "value_added": null, "value_types": ["other"], "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(726,'claude-haiku-5-5','2026-10-17T09:10:03Z',1,0.9,0,'{"areas": ["hydrology", "warnings"], "confidence": 0.9, "countries": [], "event_date": "2026-10-13", "institutions": [{"country": null, "name": "International research team", "short_name": null, "type": "research"}], "language": "en", "news_type": "pilot_research", "original_title": "AI models improve long-term flood forecasting: study-Xinhua", "primary_area": "hydrology", "relevant": true, "review": false, "summary_en": "An international research team developed AI models that could improve long-term flood forecasting, giving communities warnings weeks before floods. The findings could inform flood risk management and disaster preparedness.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "AI models improve long-term flood forecasting: study-Xinhua", "value_added": "Could provide flood warnings weeks ahead of floods, improving long-term flood forecasting.", "value_types": ["lead_time", "accuracy"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(801,'claude-haiku-5-5','2026-10-17T09:10:05Z',1,0.93,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.93, "countries": [], "event_date": "2026-10-16", "institutions": [{"country": null, "name": "European Centre for Medium-Range Weather Forecasts", "short_name": "ECMWF", "type": "WMO_centre"}], "language": "es", "news_type": "pilot_research", "original_title": "IA para mejorar pronósticos meteorológicos a 2-6 semanas", "primary_area": "guidance", "relevant": true, "review": false, "summary_en": "A post-processing layer called PBC uses AI to detect systematic errors in forecasts for weeks two to six. In tests with ECMWF, it improved 98% of precipitation forecasts and 92% of temperature forecasts. The approach targets sub-seasonal forecast guidance.", "summary_original": "La propuesta PBC actúa como capa de posprocesamiento que detecta errores sistemáticos para mejorar el pronóstico entre la semana dos y la seis. En pruebas con el ECMWF, mejora el 98 % de los pronósticos de precipitación y el 92 % de temperatura.", "system_name": "PBC", "techniques": ["ml_dl"], "title_en": "AI to improve weather forecasts at 2-6 weeks", "value_added": "Corrects systematic errors in sub-seasonal forecasts, improving 98% of precipitation and 92% of temperature forecasts in tests with ECMWF.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
