INSERT INTO "items" VALUES(134,'https://www.chinadaily.com.cn/a/202610/14/WS6acf1e51e4b06d4aa0562be5.html','https://chinadaily.com.cn/a/202610/14/WS6acf1e51e4b06d4aa0562be5.html','AI-enhanced weather forecasting boosts disaster preparedness in China - Chinadaily.com.cn','aienhancedweatherforecastingboostsdisasterpreparednessinchina','websearch_en','chinadaily.com.cn','en','2026-10-14T08:44:13Z','2026-10-17T08:44:19Z','Chinese meteorological experts said accurate and timely forecasting is critical to disaster prevention at a State Council Information Office news conference, and a CMA typhoon researcher said a hybrid AI model made an accurate call 108 hours ahead for Typhoon Bavi.',6.0,'classified',NULL,5);
INSERT INTO "items" VALUES(135,'https://suaragarut.id/en/ai-framework-improves-weather-forecasts','https://suaragarut.id/en/ai-framework-improves-weather-forecasts','AI Framework Improves Weather Forecasts Up to Six Weeks Ahead','aiframeworkimprovesweatherforecastsuptosixweeksahead','websearch_en','suaragarut.id','en','2026-10-16T08:44:13Z','2026-10-17T08:44:19Z','A Microsoft and MIT machine-learning framework (Probabilistic Bias Correction) was published in Nature on October 14, 2026, and is said to improve two-to-six-week forecasts, including extreme weather and flood predictions.',5.0,'classified',NULL,6);
INSERT INTO "items" VALUES(136,'https://kantan.news/news/artificial-intelligence-will-predict-extreme-weather-events-6-weeks-in-advance','https://kantan.news/news/artificial-intelligence-will-predict-extreme-weather-events-6-weeks-in-advance','Artificial Intelligence Will Predict Extreme Weather Events 6 Weeks in Advance','artificialintelligencewillpredictextremeweatherevents6weeksinadvance','websearch_en','kantan.news','en','2026-10-15T08:44:13Z','2026-10-17T08:44:19Z','Researchers from MIT and Microsoft reportedly developed an open-source early warning system that can predict extreme weather events up to 6 weeks in advance using the PBC model.',3.0,'classified',NULL,6);
INSERT INTO "items" VALUES(137,'https://www.noaa.gov/news-release/el-nino-looms-large-over-us-winter-outlook','https://noaa.gov/news-release/el-nino-looms-large-over-us-winter-outlook','El Nino looms large over U.S. Winter Outlook','elninoloomslargeoveruswinteroutlook','noaa_news','NOAA news','en','2026-10-14T19:40:37Z','2026-10-17T08:44:19Z','El Nino looms large over U.S. Winter Outlook Expected impacts include warmer North, wetter South and East October 15, 2026 A car drives through a snowstorm in Broomfield, Colorado, in 2024. (Image credit: Bob Hyatt/NOAA) Download Image NOAA’s U.S. Winter Outlook, released today, shows how El Nino will likely influence the upcoming winter months (December 2026 to February 2027), with warmer-than-average temperatures expected across the northern U.S.; wetter-than-average conditions likely across the southern U.S., from California to Florida, and along the Eastern Seaboard; and drought improving ',2.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(138,'https://www.noaa.gov/stories/ocean-facts-what-are-kelvin-waves-ext','https://noaa.gov/stories/ocean-facts-what-are-kelvin-waves-ext','Ocean Facts: What are Kelvin waves?','oceanfactswhatarekelvinwaves','noaa_news','NOAA news','en','2026-10-14T16:10:01Z','2026-10-17T08:44:19Z','Ocean Facts: What are Kelvin waves? Kelvin waves are difficult to see with the naked eye as they are large in scale, slow moving, and don''t break onshore like typical ocean waves. In this graphic, satellite radar altimetry measurements reveal the sea surface signature of Kelvin waves where the ocean surface is higher or lower than its long-term average. The yellow color represents elevated sea surface heights at ranges of 0 to 0.25 meters (0 to 10 inches). The red/orange color represents elevated sea surface heights at ranges of 0.25 to at least 1 meter (10 inches to at least 40 inches). (Imag',2.0,'filtered_out',NULL,NULL);
