INSERT INTO "items" VALUES(364,'https://atmarkit.itmedia.co.jp/ait/articles/2610/17/news007.html','https://atmarkit.itmedia.co.jp/ait/articles/2610/17/news007.html','「そもそも親にAIなんて必要ない」 65歳以上の生成AI利用、子世代の7割が拒否する理由','そもそも親にaiなんて必要ない65歳以上の生成ai利用子世代の7割か拒否する理由','itmedia_ai','ITmedia AI+','ja','2026-10-17T08:00:00Z','2026-10-17T08:44:33Z','SHIFT AIが65歳以上の親を持つ全国の30～50代男女723人を対象とした「シニア×AIの意識調査」の結果を発表。親に生成AIを使ってほしくない子世代が69.3％に達したという結果とともに、その理由や自身の利用頻度、親に教える際の障壁などを示した。',2.0,'filtered_out',NULL,NULL);
