INSERT INTO "items" VALUES(616,'http://www.eumetsat.int/sentinel-3c-first-images','https://eumetsat.int/sentinel-3c-first-images','Sentinel-3C first images','sentinel3cfirstimages','eumetsat','EUMETSAT news','en','2026-10-08T12:30:00Z','2026-10-17T08:55:16Z','Sentinel-3C first images Sarah Leach Thu, 08/10/2026 - 14:30 Copernicus Sentinel-3C sends its spectacular first images of Earth The third satellite launched on the Copernicus Sentinel-3 mission delivers its captivating first images Copernicus Sentinel-3C, a new satellite built to measure the colour, height and temperature of Earth’s oceans, land and ice, has sent back its first images from space. Last Updated Published on The very first image stretches from southern Germany to North Africa, with Italy and the Mediterranean Sea at its centre under largely clear skies. Captured from 30 September',1.0,'filtered_out',NULL,NULL);
