INSERT INTO "items" VALUES(626,'https://www.undrr.org/news/reduce-humanitarian-need-let-us-start-where-and-how-homes-are-built','https://undrr.org/news/reduce-humanitarian-need-let-us-start-where-and-how-homes-are-built','To reduce humanitarian need, let us start with where and how homes are built','toreducehumanitarianneedletusstartwithwhereandhowhomesarebuilt','undrr','UNDRR news','en','2026-10-13T08:59:06Z','2026-10-17T08:55:20Z','When policy, finance and implementation work together to protect where people live, resilience takes root – strengthening communities today and expanding opportunity for generations to come.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(627,'https://www.undrr.org/implementing-sendai-framework/housing-accounts-for-more-than-half-of-expected-annual-building-losses','https://undrr.org/implementing-sendai-framework/housing-accounts-for-more-than-half-of-expected-annual-building-losses','Resilience starts at home: housing accounts for more than half of expected annual building losses','resiliencestartsathomehousingaccountsformorethanhalfofexpectedannualbuildinglosses','undrr','UNDRR news','en','2026-10-13T08:56:03Z','2026-10-17T08:55:20Z','Homes account for more than half of the disaster losses expected each year across the world’s building stock, according to global risk modelling provided by the Coalition for Disaster Resilient Infrastructure (CDRI).',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(628,'https://www.undrr.org/implementing-sendai-framework/bridging-the-early-warning-to-action-gap-requires-building-resilience-at-home','https://undrr.org/implementing-sendai-framework/bridging-the-early-warning-to-action-gap-requires-building-resilience-at-home','Bridging the early warning to action gap requires building resilience at home','bridgingtheearlywarningtoactiongaprequiresbuildingresilienceathome','undrr','UNDRR news','en','2026-10-13T08:47:09Z','2026-10-17T08:55:20Z','As countries work towards the goal of Early Warnings for All, the measure of success cannot be simply whether a warning was sent or received. It must be whether people were able to use it to protect themselves and their families.',2.0,'filtered_out',NULL,NULL);
