INSERT INTO "items" VALUES(650,'https://reliefweb.int/report/world/who-pandemic-hub-sets-ambitious-goal-detect-new-outbreaks-within-24-hours','https://reliefweb.int/report/world/who-pandemic-hub-sets-ambitious-goal-detect-new-outbreaks-within-24-hours','World: WHO Pandemic Hub sets ambitious goal to detect new outbreaks within 24 hours','worldwhopandemichubsetsambitiousgoaltodetectnewoutbreakswithin24hours','reliefweb_ai','ReliefWeb - Updates','en','2026-10-13T13:38:13Z','2026-10-17T08:55:21Z','Country: World Source: World Health Organization The World Health Organization (WHO) launched a new five-year strategy for its Hub for Pandemic and Epidemic Intelligence, charting a path towards a world where every country can detect and understand emerging health threats within 24 hours of their appearance by 2030. Strengthening rapid detection is a cornerstone of global health security, helping countries contain outbreaks before they escalate into larger epidemics or spread internationally. The Hub’s strategy aims to equip every country with the capabilities needed to rapidly identify and un',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(651,'https://reliefweb.int/report/world/call-action-united-nations-general-assembly-during-its-81st-session-international-coalition-responsibility-protect','https://reliefweb.int/report/world/call-action-united-nations-general-assembly-during-its-81st-session-international-coalition-responsibility-protect','World: Call to Action for the United Nations General Assembly during its 81st session from the International Coalition for the Responsibility to Protect','worldcalltoactionfortheunitednationsgeneralassemblyduringits81stsessionfromtheinternationalcoalitionfortheresponsibilitytoprotect','reliefweb_ai','ReliefWeb - Updates','en','2026-10-13T13:33:14Z','2026-10-17T08:55:21Z','Country: World Source: Global Centre for the Responsibility to Protect Please refer to the attached file. The UN was established to uphold international peace and security, protect human rights and advance international cooperation. These commitments were reinforced at the 2005 World Summit, when member states committed to a collective Responsibility to Protect (R2P), affirming their obligation to safeguard populations from atrocity crimes, namely: genocide, war crimes, crimes against humanity and ethnic cleansing. The Outcome Document also strengthened the UN’s broader protection architecture',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(652,'https://reliefweb.int/report/world/tokyo-workshop-charts-practical-pathways-emerging-technologies-disaster-risk-reduction','https://reliefweb.int/report/world/tokyo-workshop-charts-practical-pathways-emerging-technologies-disaster-risk-reduction','World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction','worldtokyoworkshopchartspracticalpathwaysforemergingtechnologiesindisasterriskreduction','reliefweb_ai','ReliefWeb - Updates','en','2026-10-13T08:03:06Z','2026-10-17T08:55:21Z','Country: World Source: UN Office for Disaster Risk Reduction Tokyo, Japan – 2 October 2026 Governments, technology companies, researchers and international organizations came together in Tokyo from 1 to 2 October to explore how artificial intelligence and other emerging technologies can be translated into practical tools for reducing disaster risk. The Workshop on Digital and Emerging Technologies for Disaster Risk Reduction was organized by the United Nations Office for Disaster Risk Reduction (UNDRR), with the support of the Government of Japan, the Japan International Cooperation Agency (JI',2.0,'classified',NULL,3);
