INSERT INTO "items" VALUES(662,'https://blogs.nvidia.com/blog/uk-ecosystem-deployment/','https://blogs.nvidia.com/blog/uk-ecosystem-deployment','NVIDIA Announces New Investments in the UK Startup Ecosystem','nvidiaannouncesnewinvestmentsintheukstartupecosystem','nvidia_blog','NVIDIA blog','en','2026-10-14T06:04:15Z','2026-10-17T08:55:24Z','Across industries, the U.K. is putting the full stack to work. The scale of deployment is growing fast, from enterprises transforming their businesses to startups solving some of the planet’s hardest problems. NVIDIA is putting that principle into practice, including through a five-year, $250 million compute commitment to strengthen the U.K.’s agentic safety and security […]',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(663,'https://blogs.nvidia.com/blog/european-cities-agents-urban-operations/','https://blogs.nvidia.com/blog/european-cities-agents-urban-operations','European Cities Deploy NVIDIA-Powered AI Agents to Run Smarter Urban Operations','europeancitiesdeploynvidiapoweredaiagentstorunsmarterurbanoperations','nvidia_blog','NVIDIA blog','en','2026-10-14T06:00:28Z','2026-10-17T08:55:24Z','Keeping a city running means making decisions that affect residents every day — from when to repair a road to how to use energy more efficiently. Across the EMEA region, cities and local software, infrastructure and integration partners are using NVIDIA accelerated computing to build physical AI agents and digital twins that help teams make […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(664,'https://blogs.nvidia.com/blog/local-ai-rtx-spark-laptops-software-updates/','https://blogs.nvidia.com/blog/local-ai-rtx-spark-laptops-software-updates','All Systems Go: Global PC App Ecosystem Ready for NVIDIA RTX Spark','allsystemsgoglobalpcappecosystemreadyfornvidiartxspark','nvidia_blog','NVIDIA blog','en','2026-10-13T12:00:49Z','2026-10-17T08:55:24Z','NVIDIA RTX Spark is a new beginning for the PC — a reinvention combining the capabilities of a gaming PC, a creative studio and a personal AI supercomputer into a single superchip. With up to 128GB of unified memory and 1 petaflop of AI compute, RTX Spark delivers the full stack of NVIDIA RTX and […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(665,'https://blogs.nvidia.com/blog/france-ecosystem-agentic-computing/','https://blogs.nvidia.com/blog/france-ecosystem-agentic-computing','NVIDIA Announces New Investments in France’s Startups','nvidiaannouncesnewinvestmentsinfrancesstartups','nvidia_blog','NVIDIA blog','en','2026-10-13T05:00:31Z','2026-10-17T08:55:24Z','Companies in France are deploying agentic computing across industries spanning space, financial services, the public sector and scientific research, demonstrating how the country’s ecosystem has moved from ambition to application. France’s progress sits on deliberate groundwork. The AI Action Summit in February 2025 and Choose France Summits in 2025 and 2026 anchored major compute commitments […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(666,'https://blogs.nvidia.com/blog/ocp-global-summit-vera-rubin-scale-ai-factories/','https://blogs.nvidia.com/blog/ocp-global-summit-vera-rubin-scale-ai-factories','OCP Global Summit: Amid Ecosystem Adoption, NVIDIA Opens Vera Rubin Architecture to Help Scale AI Factories Worldwide','ocpglobalsummitamidecosystemadoptionnvidiaopensverarubinarchitecturetohelpscaleaifactoriesworldwide','nvidia_blog','NVIDIA blog','en','2026-10-12T15:00:25Z','2026-10-17T08:55:24Z','As AI factories grow from megawatts to gigawatts, building them takes more than advanced computing. Open standards are helping the industry scale AI infrastructure faster, more efficiently and more reliably. At the Open Compute Project (OCP) Global Summit, taking place in the San Jose McEnery Convention Center, NVIDIA announced new partnerships and contributions aimed at […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(667,'https://blogs.nvidia.com/blog/developers-simulation-frontier-ai-agents/','https://blogs.nvidia.com/blog/developers-simulation-frontier-ai-agents','Into the Omniverse: How Developers Turn Ideas Into Simulations With Frontier AI Agents','intotheomniversehowdevelopersturnideasintosimulationswithfrontieraiagents','nvidia_blog','NVIDIA blog','en','2026-10-09T16:00:35Z','2026-10-17T08:55:24Z','Turning a simulation idea into a working application means assembling assets, connecting physics and rendering, and checking that the scene behaves as intended. Developers are combining frontier AI models with NVIDIA Omniverse libraries to help carry out that work — building applications for exploring scenarios, investigating failures and improving designs. Developers direct AI agents through […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(668,'https://blogs.nvidia.com/blog/geforce-now-thursday-gears-of-war-e-day/','https://blogs.nvidia.com/blog/geforce-now-thursday-gears-of-war-e-day','Rally Up: ‘Gears of War: E-Day’ Launches on GeForce NOW','rallyupgearsofwaredaylaunchesongeforcenow','nvidia_blog','NVIDIA blog','en','2026-10-08T13:00:46Z','2026-10-17T08:55:24Z','Gears of War: E-Day leads the charge on GeForce NOW this week, bringing Marcus Fenix and Dom Santiago’s first fight against the Locust Horde to the cloud with GeForce RTX-powered performance. A new way to join the action is also coming: Fire TV users will soon be able to purchase GeForce NOW memberships directly through […]',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(669,'https://blogs.nvidia.com/blog/local-ai-rtx-spark-microsoft-windows-event/','https://blogs.nvidia.com/blog/local-ai-rtx-spark-microsoft-windows-event','NVIDIA, Microsoft Kick Off a New Beginning for Windows PCs With RTX Spark and AI Agents','nvidiamicrosoftkickoffanewbeginningforwindowspcswithrtxsparkandaiagents','nvidia_blog','NVIDIA blog','en','2026-10-07T18:45:28Z','2026-10-17T08:55:24Z','At a Microsoft event in San Francisco on Wednesday, NVIDIA founder and CEO Jensen Huang and Microsoft CEO Satya Nadella outlined how NVIDIA and Microsoft are co-engineering hardware and software for AI agents to run on Windows PCs. NVIDIA was founded because of Windows, Huang said. Now AI agents are coming to Windows. “If you […]',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(670,'https://www.microsoft.com/en-us/research/blog/simulating-student-learning-for-better-ai-tutoring/','https://microsoft.com/en-us/research/blog/simulating-student-learning-for-better-ai-tutoring','Simulating student learning for better AI tutoring','simulatingstudentlearningforbetteraitutoring','msr_blog','Microsoft Research blog','en','2026-10-12T16:00:00Z','2026-10-17T08:55:25Z','StudentSim is a research system for evaluating and improving AI tutoring tools before they are tested with learners. It models how individuals may engage with tutors, giving feedback to improve tutor performance across subjects like chess, writing, and mathematics. The post Simulating student learning for better AI tutoring appeared first on Microsoft Research .',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(671,'https://www.microsoft.com/en-us/research/blog/agent-lightning-v1-0-a-3500-line-lightweight-agentic-rl-framework-for-training-agents-with-real-harnesses/','https://microsoft.com/en-us/research/blog/agent-lightning-v1-0-a-3500-line-lightweight-agentic-rl-framework-for-training-agents-with-real-harnesses','Agent Lightning v1.0: A 3,500-Line Lightweight Agentic RL Framework for Training Agents with Real Harnesses','agentlightningv10a3500linelightweightagenticrlframeworkfortrainingagentswithrealharnesses','msr_blog','Microsoft Research blog','en','2026-10-07T16:00:00Z','2026-10-17T08:55:25Z','Training AI agents with reinforcement learning can be challenging because their tools, context, and decision-making are managed by complex frameworks. Agent Lightning connects existing agents to RL training, making it easier to improve them without rebuilding them. The post Agent Lightning v1.0: A 3,500-Line Lightweight Agentic RL Framework for Training Agents with Real Harnesses appeared first on Microsoft Research .',1.0,'filtered_out',NULL,NULL);
