INSERT INTO "stories" VALUES(7,'ai nowcast|operational_implementation','forecasting','2026-10-17T08:57:17Z','2026-10-17T08:48:44Z','2026-10-15','{"areas": ["forecasting"], "confidence": 0.95, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-15", "event_name": "AI-Nowcast", "first_seen": "2026-10-17T08:48:44Z", "id": 7, "institution_types": ["private_sector"], "institutions": [{"country": "JP", "name": "ウェザーニューズ", "short_name": "WeatherNews", "type": "private_sector"}], "languages": ["ja"], "last_updated": "2026-10-17T08:48:44Z", "news_type": "operational_implementation", "news_types": ["operational_implementation"], "primary_area": "forecasting", "review": false, "sources": [{"language": "ja", "published_at": "2026-10-15T08:48:38Z", "source_name": "news.mynavi.jp", "title": "3時間先までの強雨をAIで予測、ウェザーニューズが「AI-Nowcast」本格実装", "title_en": "WeatherNews implements AI-Nowcast to forecast heavy rain up to 3 hours ahead", "url": "https://news.mynavi.jp/techplus/article/20261015-5132256/"}], "summaries_original": {"ja": "ウェザーニューズが、3時間先までの強い雨をAIで予測する「AI-Nowcast」を本格実装した。短時間の強雨予測に用いられる。"}, "summary_en": "WeatherNews, a Japanese private weather company, has fully implemented \"AI-Nowcast,\" an AI system that predicts heavy rainfall up to three hours ahead. The system is aimed at nowcasting applications, extending short-term warning capability for strong rain.", "system_names": ["AI-Nowcast"], "techniques": ["ai_weather_model", "ml_dl"], "title": "WeatherNews implements AI-Nowcast to forecast heavy rain up to 3 hours ahead", "value_added": "Provides AI-based forecasts of heavy rain up to 3 hours ahead (nowcasting).", "value_types": ["accuracy", "lead_time"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(8,'','forecasting','2026-10-17T08:57:22Z','2026-10-17T08:48:44Z','2026-10-16','{"areas": ["forecasting"], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-16", "event_name": null, "first_seen": "2026-10-17T08:48:44Z", "id": 8, "institution_types": ["private_sector"], "institutions": [{"country": "JP", "name": "Weathernews Inc.", "short_name": "Weathernews", "type": "private_sector"}], "languages": ["ja"], "last_updated": "2026-10-17T08:48:44Z", "news_type": "other", "news_types": ["other"], "primary_area": "forecasting", "review": false, "sources": [{"language": "ja", "published_at": "2026-10-16T08:48:38Z", "source_name": "weathernews.jp", "title": "台風30号 AI予測は西寄り 物理モデルもAI予測に近づく傾向 - ウェザーニュース", "title_en": "Typhoon No. 30 AI forecast leans west; physical models also trending toward AI forecasts - Weathernews", "url": "https://weathernews.jp/news/202610/160151/"}], "summaries_original": {"ja": "台風30号の進路について、従来の物理モデルとAI予測モデルで傾向に違いが見られ、物理モデルもAI予測に近づく傾向があると伝えられています。ウェザーニューズは進路予測を最大10日先まで延長したとしています。"}, "summary_en": "Weathernews reports that the track forecast for Typhoon No. 30 differs between conventional physical models and AI forecast models, with physical models increasingly resembling AI predictions. The company says it has extended its typhoon track forecasts to as far as 10 days ahead.", "system_names": [], "techniques": ["ai_weather_model"], "title": "Typhoon No. 30 AI forecast leans west; physical models also trending toward AI forecasts - Weathernews", "value_added": "Extends typhoon track forecasts out to up to 10 days ahead, as stated by the company.", "value_types": ["lead_time"], "wmo_regions": ["II"]}');
